// Vulnerable: library code (simplified from PortSwigger's example)
const defaults = { transport_url: "https://cdn.example.com" };
function loadTransport(config) {
  const base = config.transport_url || defaults.transport_url;   // gadget
  const s = document.createElement("script");
  s.src = `${base}/example.js`;                                   // sink
  document.body.appendChild(s);
}
loadTransport({});   // app passes no transport_url

// Fixed: read only properties the caller really set
function loadTransportFixed(config) {
  const base = Object.hasOwn(config, "transport_url")
    ? config.transport_url
    : defaults.transport_url;
  const u = new URL(`${base}/example.js`);
  if (u.origin !== "https://cdn.example.com") throw new Error("bad origin");
  const s = document.createElement("script");
  s.src = u.href;
  document.body.appendChild(s);
}

