// Simplified from Next.js 15.2.3's sandbox.ts: the recursion guard
const MAX_RECURSION_DEPTH = 5;
function shouldSkipMiddleware(headers, middlewareName) {
  const subrequests = (headers["x-middleware-subrequest"] || "").split(":");
  const depth = subrequests.filter((n) => n === middlewareName).length;
  return depth >= MAX_RECURSION_DEPTH;      // "we are looping: stop"
}
// Before the fix, headers here were whatever the client sent.

const crypto = require("node:crypto");
// Generated once when the server starts; never sent to clients
const SUBREQUEST_ID = crypto.randomBytes(8).toString("hex");

function filterInternalHeaders(headers) {
  if (headers["x-middleware-subrequest-id"] !== SUBREQUEST_ID) {
    delete headers["x-middleware-subrequest"];   // not ours: drop it
  }
  delete headers["x-middleware-subrequest-id"];
  return headers;
}

