const { contextBridge, ipcRenderer } = require("electron");

// Bad: hands the page a raw IPC sender for ANY channel and ANY arguments
contextBridge.exposeInMainWorld("myAPI", {
  send: ipcRenderer.send
});

// Good: one narrow function per action, no free-form channel names
contextBridge.exposeInMainWorld("myAPI", {
  loadPreferences: () => ipcRenderer.invoke("load-prefs")
});

// main.js: check who is asking before doing anything privileged
const { ipcMain } = require("electron");
ipcMain.handle("load-prefs", (e) => {
  if (!validateSender(e.senderFrame)) return null;
  return readPrefs();
});
function validateSender(frame) {
  // Compare the origin, not the URL, against an allowlist
  return Boolean(frame && frame.origin === "https://app.example.com");
}

// main.js
const { app, shell } = require("electron");
const ALLOWED_ORIGIN = "https://app.example.com";

app.on("web-contents-created", (_event, contents) => {
  contents.on("will-navigate", (event, url) => {
    if (new URL(url).origin !== ALLOWED_ORIGIN) event.preventDefault();
  });
  contents.setWindowOpenHandler(({ url }) => {
    const u = new URL(url);
    if (u.protocol === "https:" && u.hostname === "docs.example.com") {
      setImmediate(() => shell.openExternal(u.href));   // vetted external link
    }
    return { action: "deny" };                           // never a new app window
  });
});
